package app.wakelink.android.sounds

import app.wakelink.android.data.SoundPolicy

/**
 * Names of the built-in sounds (res/raw/ringtone_<name>.ogg, generated by
 * scripts/gen-ringtones.py). The server keeps the same list in
 * server/internal/api/sounds.go; keep them in sync.
 */
val PRESET_NAMES = listOf("beep", "digital", "chime", "rising", "bell", "marimba")

/**
 * Which sound to ring with, as carried in settings, the trigger request and
 * the FCM payload:
 * - `device`: the phone's own default alarm tone
 * - `preset:<name>`: one of [PRESET_NAMES]
 * - `custom:<id>` (sender side) / `custom:<id>:<sha256>` (in the push): a
 *   recording or file the sender uploaded; the hash names the cached copy.
 */
sealed interface SoundRef {
    val key: String

    data object Device : SoundRef {
        override val key = "device"
    }

    data class Preset(val name: String) : SoundRef {
        override val key get() = "preset:$name"
    }

    data class Custom(val id: Long, val sha256: String?) : SoundRef {
        override val key get() = if (sha256 == null) "custom:$id" else "custom:$id:$sha256"
    }
}

private val SHA256_HEX = Regex("^[0-9a-f]{64}$")

/** Parses a [SoundRef.key]; null for anything malformed or unknown. */
fun parseSoundRef(key: String?): SoundRef? {
    if (key.isNullOrBlank()) return null
    if (key == SoundRef.Device.key) return SoundRef.Device
    val parts = key.split(":")
    return when (parts[0]) {
        "preset" -> parts.getOrNull(1)?.takeIf { parts.size == 2 && it in PRESET_NAMES }?.let { SoundRef.Preset(it) }
        "custom" -> {
            val id = parts.getOrNull(1)?.toLongOrNull()?.takeIf { it > 0 } ?: return null
            when (parts.size) {
                2 -> SoundRef.Custom(id, null)
                3 -> parts[2].takeIf { SHA256_HEX.matches(it) }?.let { SoundRef.Custom(id, it) }
                else -> null
            }
        }
        else -> null
    }
}

/**
 * What this device should try to play when woken: the sender's [requested]
 * sound if the receiver's [policy] allows it, otherwise the receiver's own
 * [own] sound. (If the chosen sound then fails to play, the alarm service
 * still falls back further -- see AlarmForegroundService.)
 */
fun chooseSound(requested: SoundRef?, policy: SoundPolicy, own: SoundRef): SoundRef = when {
    requested == null -> own
    policy == SoundPolicy.MINE_ONLY -> own
    policy == SoundPolicy.PRESETS_ONLY && requested is SoundRef.Custom -> own
    else -> requested
}
